import{_ as e,o as a,c,a2 as i}from"./chunks/framework.Boholvbs.js";const p=JSON.parse('{"title":"CC Switch 一键导入","description":"","frontmatter":{},"headers":[],"relativePath":"clients/cc-switch.md","filePath":"clients/cc-switch.md","lastUpdated":1791786611000}'),d={name:"clients/cc-switch.md"};function h(o,t,r,l,s,C){return a(),c("div",null,[...t[0]||(t[0]=[i('<h1 id="cc-switch-一键导入" tabindex="-1">CC Switch 一键导入 <a class="header-anchor" href="#cc-switch-一键导入" aria-label="Permalink to &quot;CC Switch 一键导入&quot;">​</a></h1><p><a href="https://github.com/farion1231/cc-switch" target="_blank" rel="noreferrer">CC Switch</a> 是一个桌面应用，用来在多个 Claude Code / Codex 服务商之间切换。装好后可以从控制台一键导入，不用手抄配置。</p><h2 id="导入" tabindex="-1">导入 <a class="header-anchor" href="#导入" aria-label="Permalink to &quot;导入&quot;">​</a></h2><ol><li>安装并至少打开一次 CC Switch（首次打开时会注册 <code>ccswitch://</code> 链接）</li><li>控制台「API 密钥」，在要导入的密钥后点「导入到 CCS」</li><li>浏览器询问是否打开 CC Switch 时选允许，CC Switch 里确认导入</li><li>在 CC Switch 里把 ai-relay 设为当前服务商</li></ol><p>导入时会按密钥所在的分组自动选目标：</p><table tabindex="0"><thead><tr><th>密钥分组</th><th>导入到</th><th>说明</th></tr></thead><tbody><tr><td>Claude 档位</td><td>Claude Code</td><td>地址 <code>https://relay.panghuli.tech</code></td></tr><tr><td>Codex 档位</td><td>Codex</td><td>地址同上，默认模型 <code>gpt-5.5</code></td></tr></tbody></table><p>导入时会同时开启 CC Switch 的用量查询，在服务商卡片上显示剩余额度。</p><h2 id="开了本地代理后请求报-401" tabindex="-1">开了本地代理后请求报 401 <a class="header-anchor" href="#开了本地代理后请求报-401" aria-label="Permalink to &quot;开了本地代理后请求报 401&quot;">​</a></h2><p>服务商的鉴权方式要选 <strong>Bearer</strong>，不要选 <code>x-api-key</code>，原因见<a href="./../guide/faq#用-cc-switch-code-switch-的本地代理时报-401「invalid-api-key」">常见问题</a>。</p><h2 id="提示「cc-switch-未安装」" tabindex="-1">提示「CC-Switch 未安装」 <a class="header-anchor" href="#提示「cc-switch-未安装」" aria-label="Permalink to &quot;提示「CC-Switch 未安装」&quot;">​</a></h2><p>说明系统没找到 <code>ccswitch://</code> 的处理程序。确认 CC Switch 已安装并打开过一次；仍不行就改用「使用密钥」手动配置，见 <a href="./claude-code">Claude Code</a> 或 <a href="./codex">Codex CLI</a>。</p>',11)])])}const w=e(d,[["render",h]]);export{p as __pageData,w as default};
